// ---- PROBE (exclusion trace) -------------------------------------------------
// The four clause bodies of the tracked TypeAnalyzer.scala:423-457, lifted out of
// pExcInner unchanged so each can be evaluated and reported on its own.
private final val probeTrace = ProjectProperties.getBoolean("probe.exclusion.trace", false)
private val probeSeen = new scala.collection.mutable.HashSet[String]()
// Variant switches: drop a clause in the POSITIVE direction only (negate==false,
// the direction definitelyExcludes asks).  The negative direction, which
// notExcludes uses to generate the equality constraints of inference
// (TypeAnalyzer.scala:361-366), is left alone.
private final val probeDropP = ProjectProperties.getBoolean("probe.exclusion.dropP", false)
private final val probeDropCC = ProjectProperties.getBoolean("probe.exclusion.dropCC", false)

protected def probeCheckEC(s: TraitType, t: TraitType)(implicit negate: Boolean, history: Set[hType]): CFormula = {
  def cEC(s: TraitType, t: TraitType) = pOr(excludesClause(s).map(pSub(t, _)))
  pOr(cEC(s, t), cEC(t, s))
}
protected def probeCheckCC(s: TraitType, t: TraitType)(implicit negate: Boolean, history: Set[hType]): CFormula =
  if (probeDropCC && !negate) pFalse() else {
  def cCC(s: TraitType, t: TraitType): CFormula = {
    val scc = comprisesClause(s)
    pAnd(pFromBoolean(!scc.isEmpty), pAnd(scc.map(pExc(t,_))))
  }
  pOr(cCC(s, t), cCC(t, s))
}
protected def probeCheckO(s: TraitType, t: TraitType)(implicit negate: Boolean, history: Set[hType]): CFormula = {
  def cO(s: TraitType, t: TraitType): CFormula = typeCons(s.getName) match {
    case _:ObjectTraitIndex => pSub(s, t)(!negate, history)
    case _ => pFalse()
  }
  pOr(cO(s,t), cO(t,s))
}
protected def probeCheckP(s: TraitType, t: TraitType)(implicit negate: Boolean, history: Set[hType]): CFormula =
  if (probeDropP && !negate) pFalse() else {
  val sas = ancestors(s) ++ Set(s)
  val tas = ancestors(t) ++ Set(t)
  def cP(s: BaseType, t: BaseType): CFormula = (s, t) match {
    case (s@STraitType(_, n1, a1, _), t@STraitType(_, n2, a2, _)) if (n1 == n2) =>
      //Todo: Handle int, nat, bool args
      pOr((a1, a2).zipped.map{
        case (STypeArg(_, _, t1), STypeArg(_, _, t2)) => pEqv(t1, t2)(!negate, history)
        case _ => pFalse()
      })
    case _ => pFalse()
  }
  pOr(for(sa <- sas; ta <- tas) yield cP(sa, ta))
}

/** Which clauses hold for this pair: a True clause is named, a clause that is
 *  neither True nor False is named with a trailing '?'. */
def probeClauses(a: CFormula, b: CFormula, c: CFormula, d: CFormula): String = {
  val all = List(("EC",a),("CC",b),("O",c),("P",d))
  val yes = all.filter(x => isTrue(x._2)).map(_._1)
  val maybe = all.filter(x => !isTrue(x._2) && !isFalse(x._2)).map(_._1 + "?")
  val r = yes ++ maybe
  if (r.isEmpty) "none" else r.mkString("+")
}

