  /** For a pair whose exclusion checkP establishes: which common generic ancestor
   *  appears at two different instantiations.  "-" when checkP does not fire. */
  def probeWitnessP(x: Type, y: Type): String = {
    implicit val pNeg: Boolean = false
    implicit val pHist: Set[hType] = Set[hType]()
    (removeSelf(normalize(removeSelf(x))), removeSelf(normalize(removeSelf(y)))) match {
      case (s: TraitType, t: TraitType) =>
        val sas = ancestors(s) ++ Set(s)
        val tas = ancestors(t) ++ Set(t)
        val ws = for {
          sa <- sas
          ta <- tas
          w <- (sa, ta) match {
            case (a@STraitType(_, n1, a1, _), b@STraitType(_, n2, a2, _)) if (n1 == n2) =>
              val f = pOr((a1, a2).zipped.map{
                case (STypeArg(_, _, t1), STypeArg(_, _, t2)) => pEqv(t1, t2)(!pNeg, pHist)
                case _ => pFalse()
              })
              if (isTrue(f)) Some(a.toString + " /vs/ " + b.toString) else None
            case _ => None
          }
        } yield w
        if (ws.isEmpty) "-" else ws.toList.distinct.sorted.mkString(" ; ")
      case _ => "-"
    }
  }

  // ---- end PROBE'''
